const { randomUUID } = require('crypto');
const envelope = $input.first().json;
if (envelope?.valid !== true || envelope?.result?.ok !== true) throw new Error('VALID_EXTRACTION_REQUIRED');
const extraction = envelope.result.extraction ?? {};
const tables = Array.isArray(extraction.tables) ? extraction.tables : [];
const markdown = String(extraction.markdown ?? extraction.text ?? '');
const structuredText = tables.map((table) => [table.headers, ...(table.rows ?? [])].flat().join(' ')).join(' ');
const text = `${markdown} ${structuredText}`.trim();
const normalized = `${extraction.file_name ?? ''} ${text}`.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const signals = ['pobj','meta','realizado','atingimento','pontuacao','pontos','consorcio','seguros','captacao','credito pj','open finance'];
const matched = signals.filter((term) => normalized.includes(term));
const fileHint = /pobj|meta|objetivo|performance/.test(String(extraction.file_name ?? '').toLowerCase());
const isPerformance = matched.length >= 2 || (fileHint && matched.length >= 1);
const decisionStatus = isPerformance ? 'READY' : 'MANUAL_REVIEW_REQUIRED';
const routing = {
  schema_version: '1.0.0',
  routing_id: randomUUID(),
  routing_method: 'DETERMINISTIC',
  rule_id: 'mvp.performance.document-signals.v1',
  intent: isPerformance ? 'ANALISAR_METAS_POBJ' : 'CLASSIFICACAO_DOCUMENTAL_INCONCLUSIVA',
  selected_domains: isPerformance ? [{
    domain: 'performance',
    requirement: 'REQUIRED',
    capabilities: ['PERFORMANCE_SOURCES_RECONCILIATION','PERFORMANCE_SCORING_STATE','PERFORMANCE_GAP_SCENARIOS']
  }] : [],
  excluded_domains: ['conta','financeiro','relacionamento'].map((domain) => ({domain, reason_code: 'NOT_REQUIRED_FOR_INTENT'})),
  dependencies: isPerformance ? [{before: 'DOCUMENT_EXTRACTION_VALIDATED', after: 'PERFORMANCE_SOURCES_RECONCILIATION'}] : [],
  fallback: 'MANUAL_REVIEW_REQUIRED',
  decision_status: decisionStatus
};
const minimalEvidence = (extraction.evidence ?? []).slice(0, 80).map(({locator,text,extraction_method,confidence}) => ({locator,text:String(text ?? '').slice(0,8000),extraction_method,confidence:confidence ?? null}));
const performanceHandoff = isPerformance ? {
  schema_version: '1.0.0',
  handoff_id: randomUUID(),
  handoff_target: 'GERENTE_GERAL_PERFORMANCE',
  job_id: envelope.job_id,
  source: {
    file_name: extraction.file_name,
    mime_type: extraction.mime_type,
    content_hash: extraction.content_hash,
    extraction_method: extraction.extraction_method,
    page_count: extraction.page_count ?? null,
    parser: extraction.parser ?? null
  },
  intent: routing.intent,
  matched_signals: matched,
  extracted_text: text.slice(0,200000),
  markdown: markdown.slice(0,200000),
  tables: tables.slice(0,100),
  sections: (extraction.sections ?? []).slice(0,500),
  extraction_warnings: extraction.warnings ?? [],
  evidence: minimalEvidence,
  capabilities: routing.selected_domains[0].capabilities,
  data_gaps: [],
  security: {content_trust: 'UNTRUSTED', external_effects_allowed: false}
} : null;
return [{json: {...envelope, routing, performance_handoff: performanceHandoff, orchestration: {director: 'DIRETOR_360_MVP', version: '1.0.0', matched_signals: matched, confidence: isPerformance ? (matched.length >= 4 ? 'HIGH' : 'MEDIUM') : 'LOW'}}}];

const perfResult = $('03 Acionar GG Performance').first()?.json ?? {};
const contaResult = $input.first()?.json ?? {};

const summaryConta = contaResult.summary ?? {};
const oppFolha = (summaryConta.opp_folha_prioritaria ?? [])[0];
const oppCobranca = (summaryConta.opp_cobranca_prioritaria ?? [])[0];
const oppVencidos = (summaryConta.opp_blindagem_vencidos ?? [])[0];

let textToAdd = '\n\n🏢 *OPORTUNIDADES DE CARTEIRA PJ (GG Conta):*\n';
if (oppFolha) textToAdd += '• *Folha de Pagamento (+4,0 pts):* ' + oppFolha.razao_social + ' (Alvo de cross-sell)\n';
if (oppCobranca) textToAdd += '• *Cobrança & PIX (+4,0 pts):* ' + oppCobranca.razao_social + ' (Ativar esteira)\n';
if (oppVencidos) textToAdd += '• *Blindagem de Vencidos (9,34 pts):* ' + oppVencidos.razao_social + ' (Monitoramento preventivo)\n';

let baseText = String(perfResult.result?.telegram_text || perfResult.telegram_text || '');
if (baseText) {
  baseText += textToAdd;
  if (perfResult.result) perfResult.result.telegram_text = baseText;
  else perfResult.telegram_text = baseText;
}

return [{
  json: {
    ...perfResult,
    conta_domain: contaResult,
    consolidated_360: {
      performance_status: perfResult.result?.status || 'READY',
      conta_status: contaResult.operating_phase || 'AVAILABLE',
      target_companies_identified: (summaryConta.opp_folha_prioritaria?.length || 0) + (summaryConta.opp_cobranca_prioritaria?.length || 0),
      decision_authority: 'RAFAEL'
    }
  }
}];
